# apply <file> <newcontent-file> <label>: replace file if content differs, report it
apply() {
  if ! cmp -s "$1" "$2"; then
    CHANGED=$((CHANGED+1))
    echo "CHANGED $3: ${1#$PROJECT/}"
    diff -u "$1" "$2" | sed -n '3,$p' | grep -E '^[-+]' | sed 's/^/    /' | head -40 || true
    [ "$DRY" = 1 ] || cat "$2" > "$1"
