      -e 's#http://xmlns\.jcp\.org/xml/ns/persistence#https://jakarta.ee/xml/ns/persistence#g' \
      -e 's#http://java\.sun\.com/xml/ns/persistence#https://jakarta.ee/xml/ns/persistence#g' \
