  for a in $EE_ANNOT; do echo "s/javax\\.annotation\\.$a\\([^A-Za-z0-9_]\\)/jakarta.annotation.$a\\1/g"; done
  echo 's/@@JDK_TX_XA@@/javax.transaction.xa/g'
