import com.acme.orders.security.JwtUtil;
import com.acme.orders.service.CustomerService;
import com.acme.orders.service.PricingClient;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class OrdersApplicationTests {
    @Autowired MockMvc mvc;
    @Autowired JwtUtil jwt;
    @Autowired CustomerRepository repo;
    @Autowired CustomerService service;
    @Autowired PricingClient pricing;

    @Test void publicEndpointIsOpen() throws Exception { mvc.perform(get("/api/public/ping/x")).andExpect(status().isOk()); }
    @Test void adminEndpointNeedsAuth() throws Exception { mvc.perform(get("/api/admin/stats")).andExpect(status().isUnauthorized()); }
    @Test @WithMockUser(roles = "USER") void adminEndpointForbiddenForUser() throws Exception { mvc.perform(get("/api/admin/stats")).andExpect(status().isForbidden()); }
    @Test @WithMockUser(roles = "ADMIN") void adminEndpointOkForAdmin() throws Exception { mvc.perform(get("/api/admin/stats")).andExpect(status().isOk()); }
    @Test void jwtRoundTrip() { assertEquals("alice", jwt.username(jwt.generate("alice"))); }
    @Test @WithMockUser(roles = "USER") void securedMethodDenied() { assertThrows(AccessDeniedException.class, () -> service.deactivate(1L)); }
    @Test @WithMockUser(roles = "ADMIN") void securedMethodAllowedAndHqlUpdateWorks() {
        Customer c = new Customer(); c.setName("Ann"); c = repo.save(c);
        assertEquals(1, service.deactivate(c.getId()));
        assertFalse(repo.findById(c.getId()).orElseThrow().isActive());
    }
    @Test void fetchJoinQueryParses() { assertNotNull(repo.findAllWithOrders()); }
    @Test void pricingFallsBackWhenRemoteDown() { assertEquals(BigDecimal.ZERO, pricing.quote("abc")); }
}
