package com.acme.orders.service;

import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import javax.sql.DataSource;
import java.math.BigDecimal;
import java.util.Map;

@Service
public class PricingClient {
    private final RestTemplate restTemplate;
    private final DataSource dataSource;

    public PricingClient(RestTemplate restTemplate, DataSource dataSource) {
        this.restTemplate = restTemplate;
        this.dataSource = dataSource;
    }

    public BigDecimal quote(String sku) {
        try {
            Map body = restTemplate.getForObject("/prices/{sku}", Map.class, sku);
            return body == null ? BigDecimal.ZERO : new BigDecimal(String.valueOf(body.get("price")));
        } catch (Exception e) {
            return BigDecimal.ZERO;
        }
    }

    public boolean hasDataSource() { return dataSource != null; }
}
